START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20260831175228_AddMenuAndTermsConditionEntities') THEN
    CREATE TABLE setup."FgsTermsCondition" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "TenantId" bigint NOT NULL,
        "CompanyId" bigint NOT NULL,
        "Code" text NOT NULL,
        "Name" text NOT NULL,
        "VersionNumber" integer NOT NULL,
        "TermsText" text NOT NULL,
        "CreatedOn" timestamptz NOT NULL,
        "CreatedBy" character varying(100),
        "UpdatedOn" timestamptz,
        "UpdatedBy" character varying(100),
        "IsActive" boolean NOT NULL,
        CONSTRAINT "PK_FgsTermsCondition" PRIMARY KEY ("Id"),
        CONSTRAINT "UQ_FgsTermsCondition" UNIQUE ("TenantId", "CompanyId", "Code", "VersionNumber"),
        CONSTRAINT "CK_FgsTermsCondition_VersionNumber" CHECK ("VersionNumber" > 0),
        CONSTRAINT "FK_FgsTermsCondition_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES setup."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT
    );
    COMMENT ON TABLE setup."FgsTermsCondition" IS 'Stores terms and conditions definitions and their versions for use across estimates, invoices, work authorizations, signatures, and other business entities.';
    COMMENT ON COLUMN setup."FgsTermsCondition"."Id" IS 'Surrogate primary key.';
    COMMENT ON COLUMN setup."FgsTermsCondition"."TenantId" IS 'Tenant that owns the terms and conditions.';
    COMMENT ON COLUMN setup."FgsTermsCondition"."CompanyId" IS 'Company within the tenant that owns the terms and conditions.';
    COMMENT ON COLUMN setup."FgsTermsCondition"."Code" IS 'Code identifying the terms and conditions definition. Multiple versions can exist for the same code.';
    COMMENT ON COLUMN setup."FgsTermsCondition"."Name" IS 'Display name of the terms and conditions.';
    COMMENT ON COLUMN setup."FgsTermsCondition"."VersionNumber" IS 'Sequential version number of the terms and conditions.';
    COMMENT ON COLUMN setup."FgsTermsCondition"."TermsText" IS 'Complete terms and conditions text for this version.';
    COMMENT ON COLUMN setup."FgsTermsCondition"."CreatedOn" IS 'UTC timestamp when the record was created.';
    COMMENT ON COLUMN setup."FgsTermsCondition"."CreatedBy" IS 'User or process that created the record.';
    COMMENT ON COLUMN setup."FgsTermsCondition"."UpdatedOn" IS 'UTC timestamp when the record was last updated.';
    COMMENT ON COLUMN setup."FgsTermsCondition"."UpdatedBy" IS 'User or process that last updated the record.';
    COMMENT ON COLUMN setup."FgsTermsCondition"."IsActive" IS 'Indicates whether the terms and conditions version is active.';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20260831175228_AddMenuAndTermsConditionEntities') THEN
    CREATE TABLE glo."GloMenu" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "MenuCode" character varying(50) NOT NULL,
        "Name" character varying(100) NOT NULL,
        "Description" character varying(255),
        "ParentMenuId" integer,
        "MenuType" character varying(20) NOT NULL,
        "Route" character varying(255),
        "Icon" character varying(100),
        "SortOrder" smallint NOT NULL DEFAULT 0,
        "IsActive" boolean NOT NULL DEFAULT TRUE,
        "CreatedOn" timestamptz NOT NULL DEFAULT (timezone('utc', now())),
        CONSTRAINT "PK_GloMenu" PRIMARY KEY ("Id"),
        CONSTRAINT "UX_GloMenu_MenuCode" UNIQUE ("MenuCode"),
        CONSTRAINT "CK_GloMenu_MenuCode_NotEmpty" CHECK (length(trim("MenuCode")) > 0),
        CONSTRAINT "CK_GloMenu_Name_NotEmpty" CHECK (length(trim("Name")) > 0),
        CONSTRAINT "FK_GloMenu_ParentMenu" FOREIGN KEY ("ParentMenuId") REFERENCES glo."GloMenu" ("Id") ON DELETE RESTRICT
    );
    COMMENT ON TABLE glo."GloMenu" IS 'Global master definition of application menus and navigation items available across the FSM platform.';
    COMMENT ON COLUMN glo."GloMenu"."Id" IS 'Unique identifier for the menu item.';
    COMMENT ON COLUMN glo."GloMenu"."MenuCode" IS 'Unique system-defined code identifying the menu item.';
    COMMENT ON COLUMN glo."GloMenu"."Name" IS 'Display name of the menu item shown to users.';
    COMMENT ON COLUMN glo."GloMenu"."Description" IS 'Description of the menu item and its purpose.';
    COMMENT ON COLUMN glo."GloMenu"."ParentMenuId" IS 'References the parent menu item when this menu is a child item; NULL for top-level menus.';
    COMMENT ON COLUMN glo."GloMenu"."MenuType" IS 'Defines the type of menu item, such as a menu group or navigable page.';
    COMMENT ON COLUMN glo."GloMenu"."Route" IS 'Application route used to navigate to the menu item when applicable.';
    COMMENT ON COLUMN glo."GloMenu"."Icon" IS 'UI icon identifier associated with the menu item.';
    COMMENT ON COLUMN glo."GloMenu"."SortOrder" IS 'Determines the display order of the menu item within its parent menu.';
    COMMENT ON COLUMN glo."GloMenu"."IsActive" IS 'Indicates whether the menu item is currently active and available for tenant configuration.';
    COMMENT ON COLUMN glo."GloMenu"."CreatedOn" IS 'UTC timestamp when the menu item was created.';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20260831175228_AddMenuAndTermsConditionEntities') THEN
    CREATE TABLE setup."FgsEntityDefaultTermsCondition" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "TenantId" bigint NOT NULL,
        "CompanyId" bigint NOT NULL,
        "EntityType" text NOT NULL,
        "TermsConditionId" bigint NOT NULL,
        "CreatedOn" timestamptz NOT NULL,
        "CreatedBy" character varying(100),
        "UpdatedOn" timestamptz,
        "UpdatedBy" character varying(100),
        "IsActive" boolean NOT NULL,
        CONSTRAINT "PK_FgsEntityDefaultTermsCondition" PRIMARY KEY ("Id"),
        CONSTRAINT "UQ_FgsEntityDefaultTermsCondition" UNIQUE ("TenantId", "CompanyId", "EntityType"),
        CONSTRAINT "FK_FgsEntityDefaultTermsCondition_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES setup."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT,
        CONSTRAINT "FK_FgsEntityDefaultTermsCondition_FgsTermsCondition_TermsConditionId" FOREIGN KEY ("TermsConditionId") REFERENCES setup."FgsTermsCondition" ("Id") ON DELETE RESTRICT
    );
    COMMENT ON TABLE setup."FgsEntityDefaultTermsCondition" IS 'Stores the default terms and conditions version assigned to each supported entity type for a tenant and company.';
    COMMENT ON COLUMN setup."FgsEntityDefaultTermsCondition"."Id" IS 'Surrogate primary key.';
    COMMENT ON COLUMN setup."FgsEntityDefaultTermsCondition"."TenantId" IS 'Tenant that owns the entity terms and conditions configuration.';
    COMMENT ON COLUMN setup."FgsEntityDefaultTermsCondition"."CompanyId" IS 'Company within the tenant for which the default terms and conditions are configured.';
    COMMENT ON COLUMN setup."FgsEntityDefaultTermsCondition"."EntityType" IS 'Entity type to which the default terms and conditions version applies, such as Invoice, Estimate, WorkAuthorization, or Signature.';
    COMMENT ON COLUMN setup."FgsEntityDefaultTermsCondition"."TermsConditionId" IS 'Reference to the specific terms and conditions version that is the default for the entity type.';
    COMMENT ON COLUMN setup."FgsEntityDefaultTermsCondition"."CreatedOn" IS 'UTC timestamp when the record was created.';
    COMMENT ON COLUMN setup."FgsEntityDefaultTermsCondition"."CreatedBy" IS 'User or process that created the record.';
    COMMENT ON COLUMN setup."FgsEntityDefaultTermsCondition"."UpdatedOn" IS 'UTC timestamp when the record was last updated.';
    COMMENT ON COLUMN setup."FgsEntityDefaultTermsCondition"."UpdatedBy" IS 'User or process that last updated the record.';
    COMMENT ON COLUMN setup."FgsEntityDefaultTermsCondition"."IsActive" IS 'Indicates whether the default entity terms and conditions mapping is active.';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20260831175228_AddMenuAndTermsConditionEntities') THEN
    CREATE TABLE glo."GloRoleMenu" (
        "RoleId" smallint NOT NULL,
        "MenuId" integer NOT NULL,
        "SortOrder" smallint NOT NULL DEFAULT 0,
        "IsActive" boolean NOT NULL DEFAULT TRUE,
        "CreatedOn" timestamptz NOT NULL DEFAULT (timezone('utc', now())),
        CONSTRAINT "PK_GloRoleMenu" PRIMARY KEY ("RoleId", "MenuId"),
        CONSTRAINT "FK_GloRoleMenu_Menu" FOREIGN KEY ("MenuId") REFERENCES glo."GloMenu" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_GloRoleMenu_Role" FOREIGN KEY ("RoleId") REFERENCES glo."GloRole" ("Id") ON DELETE CASCADE
    );
    COMMENT ON TABLE glo."GloRoleMenu" IS 'Global default mapping of standard roles to menu items used to seed tenant role menu assignments during onboarding.';
    COMMENT ON COLUMN glo."GloRoleMenu"."RoleId" IS 'References the global standard role to which the menu item is assigned.';
    COMMENT ON COLUMN glo."GloRoleMenu"."MenuId" IS 'References the global menu item assigned to the role.';
    COMMENT ON COLUMN glo."GloRoleMenu"."SortOrder" IS 'Determines the display order of the menu item for the role.';
    COMMENT ON COLUMN glo."GloRoleMenu"."IsActive" IS 'Indicates whether this default role-to-menu assignment is active and should be included when seeding tenant role menu assignments.';
    COMMENT ON COLUMN glo."GloRoleMenu"."CreatedOn" IS 'UTC timestamp when the role-to-menu assignment was created.';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20260831175228_AddMenuAndTermsConditionEntities') THEN
