    CREATE INDEX "IX_GloRoleMenu_MenuId" ON glo."GloRoleMenu" ("MenuId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20260831175228_AddMenuAndTermsConditionEntities') THEN
    INSERT INTO setup."__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20260831175228_AddMenuAndTermsConditionEntities', '10.0.8');
